+    font-weight: normal !important;
+    cursor: pointer;
+}
+
+.checkbox-label input[type="checkbox"] {
+    width: auto;
+}
+
+/* Buttons */
+.step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-next, .btn-submit {
+    padding: 0.75rem 2rem;
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    font-size: 0.9375rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+    margin-left: auto;
+}
+
+.btn-next:hover, .btn-submit:hover {
+    background: #3651d4;
+}
+
+.btn-next:disabled, .btn-submit:disabled {
+    background: #a0aec0;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    padding: 0.75rem 2rem;
+    background: #fff;
+    color: #666;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+    font-size: 0.9375rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-back:hover {
+    background: #f7f7f7;
+    border-color: #bbb;
+}
+
+.btn-add {
+    padding: 0.5rem 1rem;
+    background: #f0f4ff;
+    color: #4361ee;
+    border: 1px dashed #4361ee;
+    border-radius: 6px;
+    font-size: 0.875rem;
+    cursor: pointer;
+    transition: background 0.2s;
+    margin-top: 0.5rem;
+}
+
+.btn-add:hover {
+    background: #e0e8ff;
+}
+
+.btn-remove {
+    padding: 0.375rem 0.75rem;
+    background: #fff0f0;
+    color: #e63946;
+    border: 1px solid #ffccd5;
+    border-radius: 4px;
+    font-size: 0.8125rem;
+    cursor: pointer;
+}
+
+.btn-remove:hover {
+    background: #ffe0e0;
+}
+
+.btn-edit {
+    padding: 0.25rem 0.75rem;
+    background: transparent;
+    color: #4361ee;
+    border: 1px solid #4361ee;
+    border-radius: 4px;
+    font-size: 0.8125rem;
+    cursor: pointer;
