@namespace sv_58d46af7bef245f0919b896852e1413b.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)" @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)" disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null && Entry.StartDate != default;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value ?? "";
        Update(new WorkEntryModel(val, Entry.Title, Entry.StartDate, Entry.EndDate, Entry.Description));
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value ?? "";
        Update(new WorkEntryModel(Entry.Company, val, Entry.StartDate, Entry.EndDate, Entry.Description));
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        Update(new WorkEntryModel(Entry.Company, Entry.Title, date, Entry.EndDate, Entry.Description));
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        DateTime? date = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        Update(new WorkEntryModel(Entry.Company, Entry.Title, Entry.StartDate, date, Entry.Description));
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value ?? "";
        Update(new WorkEntryModel(Entry.Company, Entry.Title, Entry.StartDate, Entry.EndDate, val));
    }

    private void HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        DateTime? endDate = isCurrent ? null : DateTime.Today;
        Update(new WorkEntryModel(Entry.Company, Entry.Title, Entry.StartDate, endDate, Entry.Description));
    }

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
}

